import sys

def full_justify_brute(words, max_width):
    lines = []
    cur = []
    cur_len = 0
    for w in words:
        if cur and cur_len + len(w) + len(cur) > max_width:
            lines.append((cur, cur_len))
            cur = []
            cur_len = 0
        cur.append(w)
        cur_len += len(w)
    if cur:
        lines.append((cur, cur_len))

    res = []
    for idx, (line, text_len) in enumerate(lines):
        n_words = len(line)
        spaces = max_width - text_len
        if idx == len(lines) - 1 or n_words == 1:
            s = ' '.join(line)
            while len(s) < max_width:
                s += ' '
            res.append(s)
        else:
            gaps = n_words - 1
            s = ''
            for j, w in enumerate(line):
                s += w
                if j < gaps:
                    need = spaces // gaps + (1 if j < spaces % gaps else 0)
                    for _ in range(need):
                        s += ' '
            res.append(s)
    return res

