        sys.exit(0)
    m = int(data[0])
    max_width = int(data[1])
    words = data[2:2 + m]
    for line in full_justify_brute(words, max_width):
        print(line)

import sys

def full_justify_opt(words, max_width):
    lines = []
    cur = []
    cur_len = 0
    for w in words:
        if cur and cur_len + len(w) + len(cur) > max_width:
            lines.append((cur, cur_len))
            cur = []
            cur_len = 0
        cur.append(w)
        cur_len += len(w)
    if cur:
        lines.append((cur, cur_len))

    res = []
    for idx, (line, text_len) in enumerate(lines):
        gaps = len(line) - 1
        spaces = max_width - text_len
        if idx == len(lines) - 1 or gaps == 0:
            res.append(' '.join(line).ljust(max_width))
        else:
            base = spaces // gaps
            extra = spaces % gaps
            parts = []
            for j, w in enumerate(line):
                parts.append(w)
                if j < gaps:
                    parts.append(' ' * (base + (1 if j < extra else 0)))
            res.append(''.join(parts))
    return res

if __name__ == '__main__':
