    if not data:
        sys.exit(0)
    m = int(data[0])
    max_width = int(data[1])
    words = data[2:2 + m]
    for line in full_justify_opt(words, max_width):
        print(line)

import sys

def full_justify_best(words, max_width):
    res, row, row_len = [], [], 0
    for w in words:
        if row and row_len + len(w) + len(row) > max_width:
            for i in range(max_width - row_len):
                row[i % (len(row) - 1 or 1)] += ' '
            res.append(''.join(row))
            row, row_len = [], 0
        row.append(w)
        row_len += len(w)
    res.append(' '.join(row).ljust(max_width))
    return res

if __name__ == '__main__':
